<h1><?= te('Receipts and reimbursements') ?></h1><p class="sub"><?= te('Flights, hotel stays, screening and transport paid by the worker. Claims remain separate from entered timesheet expenses to avoid automatic double counting.') ?></p><?php if($own): ?><form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="claim"><label><?= te('Assignment') ?></label><select name="placement_id"><?php foreach($assignments as $a): ?><option value="<?= (int)$a['id'] ?>"><?= e($a['title']) ?></option><?php endforeach; ?></select><label><?= te('Category') ?></label><select name="category"><?php foreach(['flight','hotel','screening','transport','other'] as $x): ?><option><?= e($x) ?></option><?php endforeach; ?></select><label><?= te('Amount') ?></label><input name="amount" type="number" step="0.01" min="0.01" required><label><?= te('Receipt · upload first in Proof uploads') ?></label><select name="receipt_document_id"><?php foreach($receipts as $r): ?><option value="<?= (int)$r['id'] ?>"><?= e($r['document_type']) ?></option><?php endforeach; ?></select><label><?= te('Explanation') ?></label><textarea name="note"></textarea><button class="btn"><?= te('Submit claim') ?></button></form><?php endif; ?><?php foreach($claims as $e): ?><div class="card"><h2><?= e(($e['full_name'] ?? '').' · '.$e['title'].' · '.$e['category']) ?></h2><p><?= money($e['amount']) ?> · <?= e($e['status'].' · '.$e['payment_method'].' · '.$e['payment_reference']) ?></p><?php if(!$own && $e['status']==='submitted'): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="review"><input type="hidden" name="claim_id" value="<?= (int)$e['id'] ?>"><select name="status"><option value="approved"><?= te('approved') ?></option><option value="rejected"><?= te('rejected') ?></option></select><button class="btn"><?= te('Review') ?></button></form><?php elseif(!$own && $e['status']==='approved'): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="pay"><input type="hidden" name="claim_id" value="<?= (int)$e['id'] ?>"><select name="payment_method"><option value="direct_deposit"><?= te('direct_deposit') ?></option><option value="check"><?= te('check') ?></option><option value="cash"><?= te('cash') ?></option></select><input name="payment_reference" required placeholder="<?= te('Payment reference') ?>"><button class="btn"><?= te('Record payment') ?></button></form><?php endif; ?></div><?php endforeach; ?>